#!/usr/bin/env bash
# Copy one profile generated by the cimantic-graphs CIMTool builders into src/cimprofiles/
# and point its imports at cimprofiles. Needed until the CIMTool 2.3.1 builders emit
# cimprofiles imports themselves.
#
# usage: scripts/import_cimtool_output.sh <Profiles/name.py> <Profiles/name.__init__.py>
set -euo pipefail

if [ $# -ne 2 ]; then
    echo "usage: $0 <generated .py> <generated .__init__.py>" >&2
    exit 1
fi
profile_py=$1
init_py=$2

# The init builder imports from cimgraph.data_profile.<envelope>.<envelope>,
# so the package directory and the module must both be named <envelope>.
envelope=$(sed -n 's/^ *from cimgraph\.data_profile\.\([A-Za-z0-9_]*\)\..* import.*/\1/p' "$init_py" | head -1)
if [ -z "$envelope" ]; then
    echo "error: no 'from cimgraph.data_profile.<envelope>.<envelope> import' line in $init_py" >&2
    exit 1
fi

dest="$(cd "$(dirname "$0")/.." && pwd)/src/cimprofiles/$envelope"
mkdir -p "$dest"
cp "$profile_py" "$dest/$envelope.py"
cp "$init_py" "$dest/__init__.py"
sed -i 's/cimgraph\.data_profile\./cimprofiles./g' "$dest/$envelope.py" "$dest/__init__.py"

echo "imported $envelope into $dest"
echo "next: uv run python -m cimprofiles.dedupe_profile_fields --check && uv run pytest"
